contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint v) public payable {
        require(tos.length > 0);

        // The deciding call: either completes and returns true, or reverts.
        bool ok;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        // General rule: if transfer completes, it must return true.
        // This is the only guarantee this wrapper is intended to provide on success.
        assert(!ok || ok);
    }

    receive() external payable {}
}

